SELECT u.id, u.dept_id, u.username, u.nickname, u.email, u.phone, u.sex, u.status, u.create_time, d.name AS dept_name FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id AND d.deleted = 0 WHERE u.deleted = 0
AND u.id > #{lastId}
ORDER BY u.id ASC LIMIT 1000
